let bank=[],selected=[],submitted=false;const $=s=>document.querySelector(s),shuffle=a=>[...a].sort(()=>Math.random()-.5);
function render(){submitted=false;$('#submit').disabled=false;$('#score').textContent='';selected=shuffle(bank).slice(0,10).map(q=>({...q,o:shuffle([{t:q.correct,r:1},...q.wrong.map(t=>({t,r:0}))])}));$('#exam').innerHTML='';selected.forEach((q,i)=>{let n=$('#question').content.cloneNode(true);n.querySelector('.number').textContent=String(i+1).padStart(2,'0');n.querySelector('h2').textContent=q.prompt;q.o.forEach((o,j)=>{let l=document.createElement('label');l.className='option';l.innerHTML=`<input type="radio" name="q${i}" value="${j}"><span>${o.t}</span>`;n.querySelector('.options').append(l)});$('#exam').append(n)});$('#progress').textContent=`10 questions selected · ${bank.length} question bank`}
function grade(){if(submitted)return;submitted=true;let score=0;selected.forEach((q,i)=>{let c=$('#exam').children[i],p=c.querySelector(`input[name=q${i}]:checked`);q.o.forEach((o,j)=>{let l=c.querySelector(`input[value="${j}"]`).closest('label');l.classList.add(o.r?'correct':p?.value==j?'wrong':'dim');l.querySelector('input').disabled=true});if(p&&q.o[p.value].r)score++;let f=c.querySelector('.feedback');f.hidden=false;f.querySelector('strong').textContent=p&&q.o[p.value].r?'Correct':'Review this one';f.querySelector('p').textContent=q.explanation});$('#score').textContent=`Score: ${score}/10`;$('#submit').disabled=true}
fetch('chemistry-questions.json').then(r=>r.json()).then(d=>{bank=d.questions;if(bank.length!==100)throw Error('Need 100 questions');render()});$('#reset').onclick=render;$('#submit').onclick=grade;
